use crate::board::{Rule, RuleParseError};
use std::fmt;

#[derive(Debug, Clone)]
pub struct Pattern {
    pub name: String,
    pub cells: Vec<(usize, usize)>,
    pub width: usize,
    pub height: usize,
    /// Rule declared by the source RLE header, if it carried one.
    pub rule: Option<Rule>,
}

/// Built-in patterns as `(file stem, RLE source)`, one per file in
/// `assets/patterns/`, sorted by file name. Generated by `build.rs`.
const BUILTIN_SOURCES: &[(&str, &str)] = include!(concat!(env!("OUT_DIR"), "/builtin_patterns.rs"));

impl Pattern {
    pub fn from_rle(name: impl Into<String>, source: &str) -> Result<Self, PatternParseError> {
        let name = name.into();
        let parsed = parse_rle(source)?;
        Ok(Self {
            name,
            cells: parsed.cells,
            width: parsed.width,
            height: parsed.height,
            rule: parsed.rule,
        })
    }

    /// Parses `source`, named by its `#N` line or else `fallback`.
    pub fn from_named_rle(fallback: &str, source: &str) -> Result<Self, PatternParseError> {
        let parsed = parse_rle(source)?;
        Ok(Self {
            name: parsed.name.unwrap_or_else(|| fallback.to_owned()),
            cells: parsed.cells,
            width: parsed.width,
            height: parsed.height,
            rule: parsed.rule,
        })
    }

    /// Every file in `assets/patterns/`, named by its `#N` line or else its file
    /// name.
    pub fn builtins() -> Vec<Self> {
        BUILTIN_SOURCES
            .iter()
            .map(|&(stem, source)| {
                Self::from_named_rle(stem, source)
                    .unwrap_or_else(|err| panic!("assets/patterns/{stem}.rle: {err}"))
            })
            .collect()
    }

    pub fn builtin_count() -> usize {
        BUILTIN_SOURCES.len()
    }

    /// Position among [`Pattern::builtins`] of `assets/patterns/{stem}.rle`.
    pub fn builtin_index(stem: &str) -> Option<usize> {
        BUILTIN_SOURCES
            .iter()
            .position(|&(builtin, _)| builtin == stem)
    }
}

/// Import limits keep expansion and preview allocations bounded.
pub const MAX_PATTERN_SIDE: usize = 2048;
pub const MAX_PATTERN_CELLS: usize = MAX_PATTERN_SIDE * MAX_PATTERN_SIDE;
pub const MAX_RLE_BYTES: usize = 8 * 1024 * 1024;
/// Imported library limits, enforced on import so a workspace can always save
/// what the session holds. The board is bounded by its dimensions instead.
pub const MAX_LIBRARY_PATTERNS: usize = 256;
pub const MAX_LIBRARY_CELLS: usize = MAX_PATTERN_CELLS;
pub const MAX_PATTERN_NAME_BYTES: usize = 1024;

/// RLE lines should stay within 70 characters.
const RLE_LINE_WIDTH: usize = 70;

/// Writes `cells`, which lie within `width` x `height`, as RLE that
/// [`Pattern::from_rle`] reads back. Dead cells at the end of a row are left
/// out and runs of empty rows are merged into one `$`, as other tools expect.
/// Without a rule the header has no `rule =` field, which reads back as `None`.
pub fn to_rle(
    cells: &[(usize, usize)],
    width: usize,
    height: usize,
    rule: Option<Rule>,
    comment: &str,
) -> String {
    let mut sorted: Vec<_> = cells.iter().map(|&(x, y)| (y, x)).collect();
    sorted.sort_unstable();
    sorted.dedup();
    let mut writer = RleWriter::default();
    for (y, x) in sorted {
        writer.cells(x, y, 1);
    }
    writer.finish(width, height, rule, comment)
}

/// Builds RLE a run of live cells at a time, for patterns too big or too sparse
/// to lay out in a grid.
#[derive(Default)]
pub struct RleWriter {
    body: String,
    line_length: usize,
    token: String,
    /// Where the body has got to.
    row: usize,
    column: usize,
    /// Live cells at `(x, y)`, held back in case more follow on.
    run: Option<(usize, usize, usize)>,
}

impl RleWriter {
    /// Adds `length` live cells from `(x, y)`. Cells arrive row by row, left to
    /// right, and those next to each other in pieces make one run.
    pub fn cells(&mut self, x: usize, y: usize, length: usize) {
        if let Some(run) = &mut self.run
            && (run.0 + run.2, run.1) == (x, y)
        {
            run.2 += length;
            return;
        }
        self.write_run();
        self.run = Some((x, y, length));
    }

    fn write_run(&mut self) {
        let Some((x, y, length)) = self.run.take() else {
            return;
        };
        if y > self.row {
            self.push(y - self.row, '$');
            self.row = y;
            self.column = 0;
        }
        if x > self.column {
            self.push(x - self.column, 'b');
        }
        self.push(length, 'o');
        self.column = x + length;
    }

    fn push(&mut self, length: usize, tag: char) {
        use std::fmt::Write;
        self.token.clear();
        let written = if length == 1 {
            write!(self.token, "{tag}")
        } else {
            write!(self.token, "{length}{tag}")
        };
        written.expect("writing to a string succeeds");
        self.push_token();
    }

    fn push_token(&mut self) {
        if self.line_length + self.token.len() > RLE_LINE_WIDTH {
            self.body.push('\n');
            self.line_length = 0;
        }
        self.line_length += self.token.len();
        self.body.push_str(&self.token);
    }

    /// The complete RLE. Without a rule the header has no `rule =` field.
    pub fn finish(
        mut self,
        width: usize,
        height: usize,
        rule: Option<Rule>,
        comment: &str,
    ) -> String {
        self.write_run();
        self.token.clear();
        self.token.push('!');
        self.push_token();

        let mut rle = String::new();
        for line in comment.lines() {
            rle.push_str(&format!("#C {line}\n"));
        }
        rle.push_str(&format!("x = {width}, y = {height}"));
        if let Some(rule) = rule {
            rle.push_str(&format!(", rule = {rule}"));
        }
        rle.push('\n');
        rle.push_str(&self.body);
        rle.push('\n');
        rle
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PatternParseError {
    MissingHeader,
    MissingDimension,
    InvalidDimension,
    InvalidToken(char),
    MissingTerminator,
    Overflow,
    InvalidRule(RuleParseError),
    TooLarge,
    PlaneTooLarge,
    PlaneOutOfReach,
    OutOfBounds,
    InvalidRun,
    LibraryFull,
    NameTooLong,
}

impl fmt::Display for PatternParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::MissingHeader => write!(f, "missing RLE header line"),
            Self::MissingDimension => write!(f, "missing x/y dimension in RLE header"),
            Self::InvalidDimension => write!(f, "invalid x/y dimension in RLE header"),
            Self::InvalidToken(ch) => write!(f, "invalid RLE token '{ch}'"),
            Self::MissingTerminator => write!(f, "RLE body missing '!' terminator"),
            Self::Overflow => write!(f, "RLE run length overflows pattern bounds"),
            Self::TooLarge => write!(
                f,
                "RLE exceeds the 8 MiB input or 2048 × 2048 pattern limit"
            ),
            Self::PlaneTooLarge => write!(
                f,
                "the unbounded board has too many cells, or spreads over too many chunks, to load"
            ),
            Self::PlaneOutOfReach => {
                write!(f, "the unbounded board lies too far from the origin")
            }
            Self::OutOfBounds => write!(f, "RLE body exceeds its declared dimensions"),
            Self::InvalidRun => write!(f, "RLE counts must be positive and followed by o, b, or $"),
            Self::InvalidRule(err) => write!(f, "unsupported rule in RLE header: {err}"),
            Self::LibraryFull => write!(
                f,
                "the imported library is full (at most 256 patterns and 4,194,304 live cells)"
            ),
            Self::NameTooLong => write!(f, "pattern names may contain at most 1024 bytes"),
        }
    }
}

impl std::error::Error for PatternParseError {}

struct ParsedRle {
    /// From the first `#N` line, if any.
    name: Option<String>,
    cells: Vec<(usize, usize)>,
    width: usize,
    height: usize,
    rule: Option<Rule>,
}

fn parse_rle(source: &str) -> Result<ParsedRle, PatternParseError> {
    if source.len() > MAX_RLE_BYTES {
        return Err(PatternParseError::TooLarge);
    }
    let text = RleText::new(source)?;
    let RleHeader {
        width,
        height,
        rule,
    } = text.header;
    if width > MAX_PATTERN_SIDE || height > MAX_PATTERN_SIDE {
        return Err(PatternParseError::TooLarge);
    }
    let mut cells = Vec::new();
    // The bounds checks of the walk cap the cells at the declared area.
    walk_rle(&text.body, width, height, |x, y, length| {
        cells.extend((x..x + length).map(|x| (x, y)));
        Ok(())
    })?;
    Ok(ParsedRle {
        name: text.name,
        cells,
        width,
        height,
        rule,
    })
}

/// Reads RLE of any size a run of live cells at a time. `visit` gets each run as
/// `(x, y, length)` before it is expanded, and can stop the walk with an error.
/// Returns the width, height, and rule of the header.
pub fn read_rle_runs(
    source: &str,
    visit: impl FnMut(usize, usize, usize) -> Result<(), PatternParseError>,
) -> Result<(usize, usize, Option<Rule>), PatternParseError> {
    let text = RleText::new(source)?;
    let RleHeader {
        width,
        height,
        rule,
    } = text.header;
    walk_rle(&text.body, width, height, visit)?;
    Ok((width, height, rule))
}

/// RLE taken apart into its lines.
struct RleText {
    /// From the first `#N` line, if any.
    name: Option<String>,
    header: RleHeader,
    body: String,
}

impl RleText {
    fn new(source: &str) -> Result<Self, PatternParseError> {
        let mut header_line = None;
        let mut name = None;
        let mut body = String::new();

        for raw_line in source.lines() {
            let line = raw_line.trim();
            if let Some(title) = line.strip_prefix("#N")
                && name.is_none()
                && !title.trim().is_empty()
            {
                name = Some(title.trim().to_owned());
            }
            if line.is_empty() || line.starts_with('#') {
                continue;
            }

            if header_line.is_none() {
                header_line = Some(line.to_string());
            } else {
                body.push_str(line);
            }
        }

        let Some(header) = header_line else {
            return Err(PatternParseError::MissingHeader);
        };
        Ok(Self {
            name,
            header: parse_header(&header)?,
            body,
        })
    }
}

/// Calls `visit` with each run of live cells in `body` as `(x, y, length)`,
/// which it may trust to lie within `width` × `height`.
fn walk_rle(
    body: &str,
    width: usize,
    height: usize,
    mut visit: impl FnMut(usize, usize, usize) -> Result<(), PatternParseError>,
) -> Result<(), PatternParseError> {
    let mut x = 0usize;
    let mut y = 0usize;
    let mut run: Option<usize> = None;
    let mut terminated = false;

    for ch in body.chars() {
        match ch {
            '0'..='9' => {
                let digit = (ch as u8 - b'0') as usize;
                run = Some(
                    run.unwrap_or(0)
                        .checked_mul(10)
                        .and_then(|value| value.checked_add(digit))
                        .ok_or(PatternParseError::Overflow)?,
                );
            }
            'b' | 'o' | '$' => {
                let count = run.take().unwrap_or(1);
                if count == 0 {
                    return Err(PatternParseError::InvalidRun);
                }
                if ch == '$' {
                    y = y.checked_add(count).ok_or(PatternParseError::Overflow)?;
                    if y > height {
                        return Err(PatternParseError::OutOfBounds);
                    }
                    x = 0;
                } else {
                    let end = x.checked_add(count).ok_or(PatternParseError::Overflow)?;
                    if end > width || y >= height {
                        return Err(PatternParseError::OutOfBounds);
                    }
                    if ch == 'o' {
                        visit(x, y, count)?;
                    }
                    x = end;
                }
            }
            '!' => {
                if run.is_some() {
                    return Err(PatternParseError::InvalidRun);
                }
                // RLE readers ignore everything after the terminator, where
                // older files sometimes keep free-form notes.
                terminated = true;
                break;
            }
            ' ' | '\t' | '\r' | '\n' => {}
            _ => return Err(PatternParseError::InvalidToken(ch)),
        }
    }

    if !terminated {
        return Err(PatternParseError::MissingTerminator);
    }
    Ok(())
}

struct RleHeader {
    width: usize,
    height: usize,
    rule: Option<Rule>,
}

fn parse_header(header: &str) -> Result<RleHeader, PatternParseError> {
    let mut width = None;
    let mut height = None;
    let mut rule = None;

    for entry in header.split(',') {
        let mut parts = entry.splitn(2, '=');
        let key = parts.next().map(str::trim).unwrap_or_default();
        let value = parts.next().map(str::trim).unwrap_or_default();

        match key {
            "x" => {
                width = Some(
                    value
                        .parse::<usize>()
                        .map_err(|_| PatternParseError::InvalidDimension)?,
                );
            }
            "y" => {
                height = Some(
                    value
                        .parse::<usize>()
                        .map_err(|_| PatternParseError::InvalidDimension)?,
                );
            }
            // A declared rule used to be discarded, which silently simulated
            // non-Life patterns under B3/S23.
            "rule" => {
                rule = Some(Rule::parse(value).map_err(PatternParseError::InvalidRule)?);
            }
            _ => {}
        }
    }

    match (width, height) {
        (Some(w), Some(h)) => Ok(RleHeader {
            width: w,
            height: h,
            rule,
        }),
        _ => Err(PatternParseError::MissingDimension),
    }
}

#[cfg(test)]
mod tests {
    use super::{Pattern, PatternParseError, RleWriter, read_rle_runs, to_rle};
    use crate::board::Rule;

    #[test]
    fn parses_comments_and_run_lengths() {
        let pattern = Pattern::from_rle(
            "Three Lines",
            "#N demo\nx = 3, y = 3, rule = B3/S23\n3o$3b$3o!",
        )
        .expect("RLE should parse");

        assert_eq!(pattern.width, 3);
        assert_eq!(pattern.height, 3);
        assert_eq!(pattern.cells.len(), 6);
        assert!(pattern.cells.contains(&(0, 0)));
        assert!(pattern.cells.contains(&(2, 2)));
    }

    #[test]
    fn parses_row_break_run_counts() {
        let pattern =
            Pattern::from_rle("Row Jumps", "x = 4, y = 5\n2o2$2o!").expect("RLE should parse");

        assert!(pattern.cells.contains(&(0, 0)));
        assert!(pattern.cells.contains(&(1, 0)));
        assert!(pattern.cells.contains(&(0, 2)));
        assert!(pattern.cells.contains(&(1, 2)));
    }

    #[test]
    fn names_come_from_the_first_n_line() {
        let named = super::parse_rle("#C about\n#N  Beehive \n#N Other\nx = 1, y = 1\no!");
        assert_eq!(named.unwrap().name.as_deref(), Some("Beehive"));
        let unnamed = super::parse_rle("#N\nx = 1, y = 1\no!");
        assert_eq!(unnamed.unwrap().name, None);
    }

    #[test]
    fn every_builtin_file_parses_with_a_unique_name() {
        let builtins = Pattern::builtins();
        assert_eq!(builtins.len(), Pattern::builtin_count());
        assert!(!builtins.is_empty());
        for (index, pattern) in builtins.iter().enumerate() {
            assert!(!pattern.cells.is_empty(), "{} has no cells", pattern.name);
            assert!(
                builtins[..index]
                    .iter()
                    .all(|other| other.name != pattern.name),
                "two built-ins are named {}",
                pattern.name
            );
        }
    }

    /// Live cells after `generations`, moved so the bounding box starts at the
    /// origin, together with how far that box moved.
    fn evolve(pattern: &Pattern, generations: usize) -> (Vec<(usize, usize)>, (isize, isize)) {
        use crate::board::Board;

        let margin = 16;
        let (cols, rows) = (pattern.width + 2 * margin, pattern.height + 2 * margin);
        let mut board = Board::new(cols, rows);
        for &(x, y) in &pattern.cells {
            board.populate(x + margin, y + margin);
        }
        for _ in 0..generations {
            board.step();
        }
        let live: Vec<_> = (0..rows)
            .flat_map(|y| (0..cols).map(move |x| (x, y)))
            .filter(|&(x, y)| board.is_alive(x, y))
            .collect();
        let min_x = live.iter().map(|c| c.0).min().unwrap_or(0);
        let min_y = live.iter().map(|c| c.1).min().unwrap_or(0);
        let mut shape: Vec<_> = live.iter().map(|&(x, y)| (x - min_x, y - min_y)).collect();
        shape.sort_unstable();
        let start_x = pattern.cells.iter().map(|c| c.0).min().unwrap_or(0) + margin;
        let start_y = pattern.cells.iter().map(|c| c.1).min().unwrap_or(0) + margin;
        let moved = (
            min_x as isize - start_x as isize,
            min_y as isize - start_y as isize,
        );
        (shape, moved)
    }

    #[test]
    fn builtin_oscillators_and_spaceships_behave_as_named() {
        // The hand-written LWSS this replaced had one cell out of place and
        // fell apart instead of travelling.
        let expected = [
            ("Glider", 4, (1, 1)),
            ("LWSS", 4, (-2, 0)),
            ("Blinker", 2, (0, 0)),
            ("Pulsar", 3, (0, 0)),
            ("Pentadecathlon", 15, (0, 0)),
        ];
        let builtins = Pattern::builtins();
        for (name, period, displacement) in expected {
            let pattern = builtins
                .iter()
                .find(|pattern| pattern.name == name)
                .unwrap_or_else(|| panic!("no built-in named {name}"));
            let (start, _) = evolve(pattern, 0);
            let (end, moved) = evolve(pattern, period);
            assert_eq!(
                end, start,
                "{name} should repeat after {period} generations"
            );
            assert_eq!(moved, displacement, "{name} moved the wrong way");
        }
    }

    #[test]
    fn the_gun_fires_a_glider_every_30_generations_and_diehard_vanishes_at_130() {
        let builtins = Pattern::builtins();
        let named = |name: &str| builtins.iter().find(|p| p.name == name).unwrap();

        // Each period the gun returns to its shape plus one more glider.
        let gun = named("Gosper glider gun");
        let population = |generations| evolve(gun, generations).0.len();
        assert_eq!(population(30), gun.cells.len() + 5);
        assert_eq!(population(60), gun.cells.len() + 10);

        let diehard = named("Diehard");
        assert!(!evolve(diehard, 129).0.is_empty());
        assert!(evolve(diehard, 130).0.is_empty());
    }

    #[test]
    fn writes_rle_that_reads_back_as_the_same_cells() {
        use super::to_rle;
        use crate::board::Rule;

        let glider = [(1, 0), (2, 1), (0, 2), (1, 2), (2, 2)];
        assert_eq!(
            to_rle(&glider, 3, 3, Some(Rule::LIFE), "Glider"),
            "#C Glider\nx = 3, y = 3, rule = B3/S23\nbo$2bo$3o!\n"
        );
        let unruled = to_rle(&glider, 3, 3, None, "");
        assert_eq!(unruled, "x = 3, y = 3\nbo$2bo$3o!\n");
        assert_eq!(Pattern::from_rle("no rule", &unruled).unwrap().rule, None);

        // Empty rows inside the pattern, long runs, and a body long enough to wrap.
        let mut cells = vec![(0, 0), (39, 0), (5, 4), (6, 4), (7, 4)];
        cells.extend((0..40).step_by(2).map(|x| (x, 6)));
        let highlife = Rule::parse("B36/S23").unwrap();
        let rle = to_rle(&cells, 40, 7, Some(highlife), "two\nlines");
        assert!(rle.contains("4$"), "empty rows merge into one run: {rle}");
        assert!(rle.lines().all(|line| line.len() <= 70), "{rle}");

        let parsed = Pattern::from_rle("round trip", &rle).unwrap();
        let mut expected = cells.clone();
        expected.sort_unstable();
        let mut actual = parsed.cells.clone();
        actual.sort_unstable();
        assert_eq!(actual, expected);
        assert_eq!((parsed.width, parsed.height), (40, 7));
        assert_eq!(parsed.rule, Some(highlife));
    }

    #[test]
    fn rejects_oversized_and_malformed_runs_before_expanding() {
        for (source, error) in [
            ("x = 3, y = 3\n999999999o!", PatternParseError::OutOfBounds),
            ("x = 2049, y = 1\no!", PatternParseError::TooLarge),
            ("x = 1, y = 2049\no!", PatternParseError::TooLarge),
            ("x = 3, y = 3\n4b!", PatternParseError::OutOfBounds),
            ("x = 3, y = 3\n4$!", PatternParseError::OutOfBounds),
            ("x = 3, y = 3\n3$o!", PatternParseError::OutOfBounds),
            ("x = 0, y = 0\no!", PatternParseError::OutOfBounds),
            ("x = 3, y = 3\n0o!", PatternParseError::InvalidRun),
            ("x = 3, y = 3\n0$!", PatternParseError::InvalidRun),
            ("x = 3, y = 3\n2!", PatternParseError::InvalidRun),
        ] {
            assert_eq!(
                Pattern::from_rle("bad", source).unwrap_err(),
                error,
                "{source}"
            );
        }
        let overflow = format!("x = 3, y = 3\no{}o!", usize::MAX);
        assert_eq!(
            Pattern::from_rle("bad", &overflow).unwrap_err(),
            PatternParseError::Overflow
        );
        let overflow = format!("x = 3, y = 3\n{}0o!", usize::MAX);
        assert_eq!(
            Pattern::from_rle("bad", &overflow).unwrap_err(),
            PatternParseError::Overflow
        );
        let oversized = " ".repeat(super::MAX_RLE_BYTES + 1);
        assert_eq!(
            Pattern::from_rle("bad", &oversized).unwrap_err(),
            PatternParseError::TooLarge
        );
    }

    #[test]
    fn accepts_limit_dimensions_empty_patterns_and_trailing_row_breaks() {
        let pattern = Pattern::from_rle("edge", "x = 2048, y = 2048\n2047b$o!").unwrap();
        assert_eq!((pattern.width, pattern.height), (2048, 2048));
        assert_eq!(pattern.cells, vec![(0, 1)]);
        assert!(
            Pattern::from_rle("empty", "x = 0, y = 0\n!")
                .unwrap()
                .cells
                .is_empty()
        );
        let pattern = Pattern::from_rle("last", "x = 1, y = 1\no$!").unwrap();
        assert_eq!((pattern.width, pattern.height), (1, 1));
        // Notes after the terminator, even ones that look like cells, are ignored.
        let pattern =
            Pattern::from_rle("notes", "x = 2, y = 1\no!o 999999999o\nFound by hand.").unwrap();
        assert_eq!(pattern.cells, vec![(0, 0)]);
    }

    #[test]
    fn rejects_missing_terminator() {
        let result = Pattern::from_rle("Bad", "x = 3, y = 3\n3o$3o");
        assert_eq!(result.err(), Some(PatternParseError::MissingTerminator));
    }

    #[test]
    fn the_writer_joins_pieces_of_a_run_and_skips_empty_rows_and_gaps() {
        let mut writer = RleWriter::default();
        writer.cells(2, 0, 64);
        writer.cells(66, 0, 6);
        writer.cells(80, 0, 1);
        writer.cells(1, 4, 1);
        assert_eq!(
            writer.finish(81, 5, None, ""),
            "x = 81, y = 5\n2b70o8bo4$bo!\n"
        );
    }

    #[test]
    fn long_rows_wrap_at_the_line_width_and_read_back() {
        let cells: Vec<_> = (0..200).map(|x| (x * 2, 0)).collect();
        let rle = to_rle(&cells, 399, 1, None, "");
        let lines = rle.lines().skip(1);
        assert!(lines.clone().count() > 1);
        assert!(lines.clone().all(|line| line.len() <= 70), "{rle}");
        assert_eq!(Pattern::from_rle("Long", &rle).unwrap().cells, cells);
    }

    #[test]
    fn the_writer_starts_where_the_first_cell_is() {
        let mut writer = RleWriter::default();
        writer.cells(3, 2, 1);
        assert_eq!(writer.finish(4, 3, None, ""), "x = 4, y = 3\n2$3bo!\n");
    }

    #[test]
    fn cells_in_any_order_and_with_repeats_write_the_same() {
        assert_eq!(
            to_rle(&[(1, 1), (0, 0), (1, 1), (2, 1)], 3, 2, None, ""),
            to_rle(&[(0, 0), (1, 1), (2, 1)], 3, 2, None, "")
        );
    }

    #[test]
    fn runs_read_at_any_size_and_stop_when_told_to() {
        let source = "#C note\nx = 5000, y = 3000, rule = B36/S23\n4999bo2999$3o!";
        let mut runs = Vec::new();
        let (width, height, rule) = read_rle_runs(source, |x, y, length| {
            runs.push((x, y, length));
            Ok(())
        })
        .unwrap();
        assert_eq!((width, height), (5000, 3000));
        assert_eq!(rule, Some(Rule::parse("B36/S23").unwrap()));
        assert_eq!(runs, vec![(4999, 0, 1), (0, 2999, 3)]);

        // Before anything has to be laid out for it.
        let huge = "x = 9000000000, y = 1\n9000000000o!";
        let stopped = read_rle_runs(huge, |_, _, length| {
            assert_eq!(length, 9_000_000_000);
            Err(PatternParseError::PlaneTooLarge)
        });
        assert!(matches!(stopped, Err(PatternParseError::PlaneTooLarge)));

        let past_the_end = read_rle_runs("x = 2, y = 1\n3o!", |_, _, _| Ok(()));
        assert!(matches!(past_the_end, Err(PatternParseError::OutOfBounds)));
    }
}
